from pathlib import Path
from playwright.sync_api import sync_playwright
R=Path(__file__).parent
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox','--disable-dev-shm-usage','--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader'])
 p=b.new_page(viewport={'width':1440,'height':980},accept_downloads=True);errors=[];p.on('pageerror',lambda e:errors.append(str(e)))
 # Actual page source with local assets inlined because navigation is blocked by policy.
 import base64
 html=(R/'index.html').read_text()
 for name in ('assets.js','graph.js','ui.js','model-library.js'):
  html=html.replace(f'<script src="{name}?v=03a"></script>','<script>'+(R/name).read_text()+'</script>')
 html=html.replace('src="offline-reference.png"','src="data:image/png;base64,'+base64.b64encode((R/'offline-reference.png').read_bytes()).decode()+'"')
 p.set_content(html);p.wait_for_function('window.leanState && leanState().parts.length===28');p.wait_for_timeout(200)
 def state():return p.evaluate('leanState()')
 def click(id):p.locator('#'+id).click()
 def check(name,cond):assert cond,name;print('PASS',name)
 check('five catalog types and standard assembly',p.locator('#catalog .asset').count()==5 and state()['parts'].__len__()==28)
 p.locator('#beam').fill('800');click('resizeframe');check('template resize via UI',state()['template']['beam_mm']==800 and next(x for x in state()['parts'] if x['id']=='right')['position'][0]==840)
 p.screenshot(path=str(R/'preview-ui.png'))
 click('free');click('insert');p.locator('#orientation').select_option('X');p.locator('#x').fill('100');click('insert');check('free insert two profiles',len(state()['parts'])==2)
 click('attach');check('auto mate and hardware',len(state()['parts'])==7 and len(state()['joints'])==8 and state()['parts'][1]['position']==[20,0,20]);p.locator('#partlist').select_option('P2');click('capb');p.locator('#editlength').fill('800');click('resizepart');check('free resize cap follows',next(x for x in state()['parts'] if x['id']=='P2-cap-b')['position']==[820,0,20])
 p.locator('#partlist').select_option('C3-bracket');check('rigid edit disabled',p.locator('#editlength').is_disabled());p.locator('#partlist').select_option('P2');before=state()
 with p.expect_download() as d:click('save')
 d.value.save_as(R/'saved-example.json');click('remove');check('delete cascades',len(state()['parts'])==1);click('undo');check('undo restores graph',state()==before);click('free');p.locator('#importfile').set_input_files(R/'saved-example.json');p.wait_for_function('leanState().parts.length===8');check('JSON import restores design',state()==before)
 check('BOM reflects active graph',sum(int(x.inner_text()) for x in p.locator('#bom tr td:last-child').all())==8)
 click('free');click('insert');check('first inserted part auto selected',p.evaluate('leanSelection()')=='P1' and p.locator('#applypos').is_enabled());p.locator('#catalog button').click();check('catalog click inserts and offsets duplicate start',len(state()['parts'])==2 and state()['parts'][1]['position']==[100,80,0] and p.evaluate('leanSelection()')=='P2');p.locator('#posx').fill('240');p.locator('#posy').fill('160');p.locator('#posz').fill('50');click('applypos');check('coordinate edit updates graph',state()['parts'][1]['position']==[240,160,50]);click('undo');check('coordinate move undo',state()['parts'][1]['position']==[100,80,0])
 def active(id):return p.locator('#'+id).get_attribute('aria-pressed')=='true'
 def color(selector):return p.locator(selector).evaluate('(e)=>getComputedStyle(e).backgroundColor')
 check('free mode active color and status',active('free') and not active('standard') and color('#free')=='rgb(230, 195, 94)' and '自由搭建' in p.locator('#mode-status').inner_text())
 profile=p.locator('#catalog [data-kind=profile]');check('catalog selected visible highlight',profile.get_attribute('data-selected')=='true' and color('#catalog [data-kind=profile]')=='rgb(255, 240, 186)' and '已选中 P2' in profile.inner_text())
 p.evaluate("leanSelect('')");check('catalog clears on deselection',profile.get_attribute('data-selected')=='false')
 p.locator('#partlist').select_option('P1');check('tree selection syncs catalog',profile.get_attribute('data-selected')=='true' and '已选中 P1' in profile.inner_text())
 click('standard');check('standard mode active, free inactive',active('standard') and not active('free') and color('#standard')=='rgb(230, 195, 94)' and profile.is_disabled() and profile.get_attribute('data-selected')=='false')
 click('undo');check('undo restores mode and catalog',active('free') and not active('standard') and profile.get_attribute('data-selected')=='true')
 click('standard');p.locator('#importfile').set_input_files(R/'saved-example.json');p.wait_for_function("leanState().mode==='free'");check('import restores mode indicators',active('free') and not active('standard'))
 click('standard');click('frame3d');check('space template generated',len(state()['parts'])==100 and len(state()['joints'])==136 and p.locator('#depthrow').is_visible())
 p.locator('#beam').fill('800');p.locator('#depth').fill('600');p.locator('#post').fill('900');click('resizeframe');check('space template resize XYZ',state()['template']['depth_mm']==600 and next(x for x in state()['parts'] if x['id']=='post-11')['position']==[840,640,0])
 click('tofree');check('convert to free preserves geometry and mode UI',len(state()['parts'])==100 and active('free') and not active('standard'))
 p.locator('#connection').select_option('x-0-bottom-0');click('detach');check('detach removes hardware, not profiles',len(state()['parts'])==95 and len(state()['joints'])==128)
 click('undo');check('undo restores connection',len(state()['parts'])==100 and len(state()['joints'])==136)
 p.locator('#partlist').select_option('x-0-bottom');p.locator('#editlength').fill('900');click('resizepart');check('closed-loop resize rejection visible',len(state()['parts'])==100 and '闭环' in p.locator('#message').inner_text())
 click('free');p.locator('#orientation').select_option('Z');p.locator('#x').fill('0');p.locator('#y').fill('0');p.locator('#z').fill('0');click('insert');p.locator('#x').fill('540');click('insert');p.locator('#orientation').select_option('X');p.locator('#x').fill('20');p.locator('#z').fill('20');click('insert');p.locator('#vertical').select_option('P1');p.locator('#horizontal').select_option('P3');p.locator('#side').select_option('left');p.locator('#level').select_option('bottom');click('attach');p.locator('#vertical').select_option('P2');p.locator('#side').select_option('right');click('attach');check('free second end via UI',len(state()['connections'])==2 and len(state()['parts'])==13)
 p.locator('#partlist').select_option('P3');p.locator('#editlength').fill('800');click('resizepart');check('free double-end resize via UI',next(x for x in state()['parts'] if x['id']=='P2')['position']==[840,0,0] and sum(int(x.inner_text()) for x in p.locator('#bom tr td:last-child').all())==13)
 click('undo');check('undo bridge resize',next(x for x in state()['parts'] if x['id']=='P2')['position']==[540,0,0])
 click('model-load');check('workdesk library load',len(state()['parts'])==85 and state()['template']['parameters']['length_mm']==1500 and p.locator('#model-config').is_visible())
 p.locator('#partlist').select_option(next(x['id'] for x in state()['parts'] if x['kind']=='profile' and x['rotation'][0][2]==1));check('selection maps to X parameter','长度 X' in p.locator('#model-group-label').inner_text())
 p.locator('#model-group-value').fill('1800');click('model-group-update');check('selected group changes whole model',state()['template']['parameters']['length_mm']==1800 and state()['template']['parameters']['frame_height_mm']==870 and len(state()['parts'])==85)
 click('undo');check('undo model configuration',state()['template']['parameters']['length_mm']==1500)
 click('tofree');check('model converts to free',state()['mode']=='free' and len(state()['parts'])==85 and not p.locator('#model-config').is_visible())
 check('no uncaught browser errors',not errors);print('RENDER STATUS:',p.locator('#renderstatus').inner_text());print('WebGL2:',p.evaluate("!!document.createElement('canvas').getContext('webgl2')"));b.close()
